  trapTitle: {
    en: (a, b) => b ? `Why so high between ${a} and ${b}?` : `What happens at low pay?`,
    nl: (a, b) => b ? `Waarom zo hoog tussen ${a} en ${b}?` : `Wat gebeurt er bij een laag loon?`,
    fr: (a, b) => b ? `Pourquoi si élevé entre ${a} et ${b} ?` : `Que se passe-t-il aux bas salaires ?`,
  },
  trapBody: {
    en: (a, b, kgb) => b
      ? `Once the household earns more than €29 736, the health-care allowance drops by 13.73 cents for each extra euro${kgb ? `, and the child budget (up to ${kgb} a year) by 7.6 cents` : ''}. You also pay 35.75% or 37.56% tax, and your general tax credit shrinks by 6.4 cents per euro. So of each extra euro you earn, you keep far less than half. The allowances stop at ${b}.`
      : `From the minimum wage of ${a}, the labour credit (a tax discount for working) grows with your pay up to €45 592. That keeps your tax low. At the same time, the general tax credit starts to shrink from €29 736. Switch on the allowances to see what they add.`,
    nl: (a, b, kgb) => b
      ? `Zodra het gezin meer dan € 29.736 verdient, daalt de zorgtoeslag met 13,73 cent per extra euro${kgb ? `, en het kindgebonden budget (tot ${kgb} per jaar) met 7,6 cent` : ''}. Je betaalt ook 35,75% of 37,56% belasting, en je algemene heffingskorting daalt met 6,4 cent per euro. Van elke extra euro hou je dus veel minder dan de helft over. De toeslagen stoppen bij ${b}.`
      : `Vanaf het minimumloon van ${a} groeit de arbeidskorting (een belastingkorting omdat je werkt) mee met je loon tot € 45.592. Zo blijft je belasting laag. Tegelijk begint de algemene heffingskorting te dalen vanaf € 29.736. Zet de toeslagen aan om te zien wat ze toevoegen.`,
    fr: (a, b, kgb) => b
      ? `Dès que le foyer gagne plus de 29 736 €, l'allocation santé baisse de 13,73 centimes par euro gagné en plus${kgb ? `, et le budget enfant (jusqu'à ${kgb} par an) de 7,6 centimes` : ''}. Vous payez aussi 35,75% ou 37,56% d'impôt, et votre crédit d'impôt général baisse de 6,4 centimes par euro. Sur chaque euro gagné en plus, vous gardez donc bien moins de la moitié. Les allocations s'arrêtent à ${b}.`
      : `Dès le salaire minimum de ${a}, le crédit pour revenus du travail (une réduction d'impôt parce que vous travaillez) augmente avec votre salaire jusqu'à 45 592 €. Cela garde votre impôt bas. En même temps, le crédit d'impôt général commence à baisser à partir de 29 736 €. Activez les allocations pour voir ce qu'elles ajoutent.`,
  },
  topTitle: {
    en: (top, end) => `Why the jump between ${top} and ${end}?`,
    nl: (top, end) => `Waarom de sprong tussen ${top} en ${end}?`,
    fr: (top, end) => `Pourquoi la hausse entre ${top} et ${end} ?`,
  },
  topBody: {
    en: (top, end, rate, topRate) => `Above €78 426 you pay 49.5% tax. At the same time the labour credit keeps shrinking by 6.51 cents per euro, until it's gone at €132 920. Together that takes ${rate} of each extra euro. Above that, only the ${topRate} rate is left. Your employer stops paying premiums above €79 409, so a raise costs them less from there.`,
    nl: (top, end, rate, topRate) => `Boven € 78.426 betaal je 49,5% belasting. Tegelijk daalt de arbeidskorting nog met 6,51 cent per euro, tot ze weg is bij € 132.920. Samen gaat er ${rate} van elke extra euro af. Daarboven blijft alleen het tarief van ${topRate}. Je werkgever betaalt geen premies meer boven € 79.409, dus vanaf daar kost een loonsverhoging hem minder.`,
    fr: (top, end, rate, topRate) => `Au-delà de 78 426 €, vous payez 49,5% d'impôt. En même temps, le crédit pour revenus du travail baisse encore de 6,51 centimes par euro, jusqu'à disparaître à 132 920 €. Ensemble, cela prend ${rate} de chaque euro en plus. Au-delà, il ne reste que le taux de ${topRate}. Votre employeur ne paie plus de cotisations au-delà de 79 409 €, donc une augmentation lui coûte moins cher à partir de là.`,
  },

